package com.spinplayer.app;
import android.app.*;import android.content.*;import android.os.*;import android.net.*;import android.media.*;import android.provider.MediaStore;import java.io.*;import java.util.*;import org.json.*;
/** Sequential, persisted queue. Interruption is visible; never publishes partial audio. */
public class DownloadService extends Service {
 public static volatile DownloadService instance;volatile boolean stop;volatile long active;Thread worker;volatile int lastStartId;
 public void onCreate(){super.onCreate();instance=this;getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("downloads","Загрузка музыки",NotificationManager.IMPORTANCE_LOW));}
 Notification notification(String text){return new Notification.Builder(this,"downloads").setSmallIcon(R.drawable.ic_notification).setContentTitle("SPIN · Загрузка").setContentText(text).setOnlyAlertOnce(true).setContentIntent(PendingIntent.getActivity(this,2,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build();}
 public int onStartCommand(Intent i,int flags,int id){if(id>0)lastStartId=id;startForeground(22,notification("Подготовка очереди"));if(worker==null||!worker.isAlive()){stop=false;worker=new Thread(()->{PowerManager.WakeLock wake=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"SPIN:downloads");wake.acquire(60*60*1000L);try{runQueue();}finally{if(wake.isHeld())wake.release();worker=null;if(!stop&&OnlineDownloads.next(this)!=null&&wifiAllowed()){new Handler(Looper.getMainLooper()).post(()->onStartCommand(new Intent(),0,0));}else{stopForeground(STOP_FOREGROUND_REMOVE);stopSelfResult(lastStartId);}}},"spin-downloads");worker.start();}return START_NOT_STICKY;}
 boolean wifiAllowed(){if(!getSharedPreferences("spin",0).getBoolean("wifiOnly",false))return true;ConnectivityManager c=getSystemService(ConnectivityManager.class);NetworkCapabilities n=c.getNetworkCapabilities(c.getActiveNetwork());return n!=null&&n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI);}
 void runQueue(){YtDlpEngine.Events events=new YtDlpEngine.Events(){public boolean cancelled(){return stop||!wifiAllowed()||!OnlineDownloads.exists(DownloadService.this,active);}public void log(String s){if(s.startsWith("YTDLP_SPIN|")){String[] f=s.split("\\|");try{OnlineDownloads.progress(DownloadService.this,active,Long.parseLong(f[2]),f[3].equals("NA")?-1:Long.parseLong(f[3]),f[4].equals("NA")?0:Double.parseDouble(f[4]));}catch(Exception ignored){}}}};YtDlpEngine engine=new YtDlpEngine(this,events);while(!stop){JSONObject job=OnlineDownloads.next(this);if(job==null)return;active=job.optLong("id");File dir=new File(getCacheDir(),"download-"+active);long begin=System.nanoTime();Uri published=null;try{if(getSharedPreferences("spin",0).getBoolean("wifiOnly",false)){NetworkCapabilities cap=getSystemService(ConnectivityManager.class).getNetworkCapabilities(getSystemService(ConnectivityManager.class).getActiveNetwork());if(cap==null||!cap.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)){OnlineDownloads.update(this,active,"waiting","Ожидание Wi-Fi. Нажми «Продолжить» после подключения.");return;}}
 OnlineDownloads.update(this,active,"running","");getSystemService(NotificationManager.class).notify(22,notification(job.optString("artist")+" — "+job.optString("name")));File file;if(YandexCatalog.accepts(job.getString("url"))){file=new YandexCatalog(this).download(job,dir,events);}else{engine.init();String audioUrl=job.getString("url");if(SpotifyCatalog.accepts(audioUrl)){JSONObject matched=SpotifyCatalog.match(this,job,events);audioUrl=matched.getString("url");job.put("audioSourceUrl",audioUrl);OnlineDownloads.audioSource(this,active,audioUrl);}file=engine.download(audioUrl,dir,job.optString("formatKey","best"));}if(stop||!OnlineDownloads.exists(this,active))throw new IOException("Отменено");MediaExtractor extractor=new MediaExtractor();long duration=0;boolean audio=false;try{extractor.setDataSource(file.getAbsolutePath());for(int k=0;k<extractor.getTrackCount();k++){MediaFormat f=extractor.getTrackFormat(k);if(f.getString(MediaFormat.KEY_MIME).startsWith("audio/")){audio=true;if(f.containsKey(MediaFormat.KEY_DURATION))duration=f.getLong(MediaFormat.KEY_DURATION)/1000;break;}}}finally{extractor.release();}if(!audio||file.length()==0)throw new IOException("Файл не содержит аудио");AudioValidator.verify(file);if(YandexCatalog.accepts(job.getString("url"))&&job.optDouble("duration")>0&&Math.abs(duration/1000.0-job.optDouble("duration"))>Math.max(5,job.optDouble("duration")*.05))throw new IOException("Сервис вернул только фрагмент или запись другой длительности");cacheCover(job.optString("cover"));published=publish(file,job);OnlineDownloads.completed(this,active,published,file.length(),duration,(System.nanoTime()-begin)/1000000);
 }catch(Exception e){if(published!=null)getContentResolver().delete(published,null,null);if(OnlineDownloads.exists(this,active))OnlineDownloads.update(this,active,wifiAllowed()?"failed":"waiting",wifiAllowed()?safe(e):"Ожидание Wi-Fi. Нажми «Продолжить».");}finally{YtDlpEngine.delete(dir);active=0;}}}
 void cacheCover(String raw){try{ArtworkCache.load(this,raw);}catch(Exception ignored){}}
 String safe(Exception e){String s=e.getMessage();if(e instanceof java.net.UnknownHostException)return "Источник недоступен. Проверь сеть / VPN";if(s!=null&&s.matches("YtDlp[A-Za-z]+"))return "yt-dlp: "+s.substring(5)+". Попробуй другую запись или сеть.";if(s!=null&&(s.startsWith("Неуверенное")||s.startsWith("Подключи")||s.startsWith("Яндекс")||s.startsWith("Не найдена")||s.startsWith("Сервис")||s.startsWith("Выбранное")))return s;return "Загрузка не завершена: "+e.getClass().getSimpleName();}
 Uri publish(File f,JSONObject job)throws Exception{String ext=f.getName().substring(f.getName().lastIndexOf('.')+1);ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,OnlineDownloads.clean(job.optString("artist")+" - "+job.optString("name"))+"."+ext);values.put(MediaStore.Audio.Media.TITLE,job.optString("name"));values.put(MediaStore.Audio.Media.ARTIST,job.optString("artist"));values.put(MediaStore.Audio.Media.ALBUM,job.optString("album"));values.put(MediaStore.Audio.Media.MIME_TYPE,ext.equals("m4a")?"audio/mp4":ext.equals("webm")?"audio/webm":ext.equals("mp3")?"audio/mpeg":"audio/ogg");values.put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/SPIN/"+OnlineDownloads.clean(job.optString("artist"))+"/"+OnlineDownloads.clean(job.optString("album")));values.put(MediaStore.Audio.Media.IS_PENDING,1);Uri uri=getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("MediaStore");try{try(InputStream in=new FileInputStream(f);OutputStream out=getContentResolver().openOutputStream(uri)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(stop||!OnlineDownloads.exists(this,active))throw new IOException("Cancelled");out.write(b,0,n);}}values.clear();values.put(MediaStore.Audio.Media.IS_PENDING,0);getContentResolver().update(uri,values,null,null);return uri;}catch(Exception e){getContentResolver().delete(uri,null,null);throw e;}}
 public void onTimeout(int id,int type){stop=true;OnlineDownloads.update(this,active,"failed","Android остановил длительную загрузку. Повтори её из очереди.");stopSelf();}
 public void onDestroy(){stop=true;instance=null;super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
